mapper.select:
SELECT pio.id, pio.inbound_no, pio.return_type, pio.ref_no, pio.shipping_order_id, so.shipping_no AS shipping_order_no, so.provider_id, pio.erp_tenant_id, pio.warehouse_id, w.warehouse_name, pio.inbound_date, pio.order_status, pio.receive_by, COALESCE(NULLIF(receive_user.nickname, ''), receive_user.username) AS receive_by_name, pio.receive_time, pio.putaway_by, COALESCE(NULLIF(putaway_user.nickname, ''), putaway_user.username) AS putaway_by_name, pio.putaway_time, pio.create_time FROM wms_purchase_inbound_order pio LEFT JOIN wms_shipping_order so ON pio.shipping_order_id = so.id LEFT JOIN wms_warehouse w ON pio.warehouse_id = w.id LEFT JOIN sys_user receive_user ON pio.receive_by = receive_user.user_id AND receive_user.deleted = 0 LEFT JOIN sys_user putaway_user ON pio.putaway_by = putaway_user.user_id AND putaway_user.deleted = 0
pio.deleted = 0
AND pio.inbound_no LIKE CONCAT('%', #{qo.inboundNo}, '%')
AND so.shipping_no LIKE CONCAT('%', #{qo.shippingOrderNo}, '%')
AND EXISTS ( SELECT 1 FROM wms_purchase_inbound_order_item pioi INNER JOIN wms_purchase_order po ON pioi.purchase_order_id = po.id WHERE pioi.inbound_order_id = pio.id AND po.order_no LIKE CONCAT('%', #{qo.purchaseOrderNo}, '%') )
AND pio.warehouse_id = #{qo.warehouseId}
AND pio.order_status = #{qo.orderStatus}
AND pio.order_status IN
#{st}
AND pio.source_type = #{qo.sourceType}
AND pio.return_type = #{qo.returnType}
AND pio.erp_tenant_id = #{qo.erpTenantId}
AND EXISTS ( SELECT 1 FROM sys_tenant ot WHERE ot.id = pio.erp_tenant_id AND ot.parent_wms_tenant_id = #{qo.wmsTenantId} )
AND pio.receive_by = #{qo.receiveBy}
AND pio.putaway_by = #{qo.putawayBy}
AND pio.inbound_date >= #{qo.inboundDateStart}
AND pio.inbound_date <= #{qo.inboundDateEnd}
AND EXISTS ( SELECT 1 FROM wms_purchase_inbound_order_item pioi WHERE pioi.inbound_order_id = pio.id AND pioi.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%') )
ORDER BY pio.create_time DESC

SELECT * FROM wms_purchase_inbound_order
WHERE inbound_no = #{inboundNo}

    AND id != #{excludeId}

LIMIT 1

SELECT pio.id, pio.inbound_no, pio.return_type, pio.ref_no, pio.shipping_order_id, so.shipping_no AS shipping_order_no, so.provider_id, pio.warehouse_id, w.warehouse_name, pio.inbound_date, pio.order_status, pio.create_time FROM wms_purchase_inbound_order pio LEFT JOIN wms_shipping_order so ON pio.shipping_order_id = so.id LEFT JOIN wms_warehouse w ON pio.warehouse_id = w.id
pio.deleted = 0
AND pio.inbound_no LIKE CONCAT('%', #{qo.inboundNo}, '%')
AND so.shipping_no LIKE CONCAT('%', #{qo.shippingOrderNo}, '%')
AND EXISTS ( SELECT 1 FROM wms_purchase_inbound_order_item pioi INNER JOIN wms_purchase_order po ON pioi.purchase_order_id = po.id WHERE pioi.inbound_order_id = pio.id AND po.order_no LIKE CONCAT('%', #{qo.purchaseOrderNo}, '%') )
AND pio.warehouse_id = #{qo.warehouseId}
AND pio.order_status = #{qo.orderStatus}
AND pio.source_type = #{qo.sourceType}
AND pio.return_type = #{qo.returnType}
AND pio.erp_tenant_id = #{qo.erpTenantId}
AND pio.inbound_date >= #{qo.inboundDateStart}
AND pio.inbound_date <= #{qo.inboundDateEnd}
AND EXISTS ( SELECT 1 FROM wms_purchase_inbound_order_item pioi WHERE pioi.inbound_order_id = pio.id AND pioi.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%') )
ORDER BY pio.create_time DESC

SELECT pio.shipping_order_id AS shippingOrderId, SUM(pioi.actual_quantity) AS inboundedQuantity FROM wms_purchase_inbound_order pio INNER JOIN wms_purchase_inbound_order_item pioi ON pio.id = pioi.inbound_order_id WHERE pio.shipping_order_id IN
#{id}
AND pio.order_status IN ('RECEIVED', 'COMPLETED') AND pio.deleted = 0 GROUP BY pio.shipping_order_id
